function ev(k){return (services.externalVars && services.externalVars[k])?services.externalVars[k]:null;}
function escapeHtml(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
const esc = escapeHtml;
function nl2br(s){return escapeHtml(s).replace(/\n/g,'<br>');}
function hmToMin(hm){var p=String(hm||'').split(':');return (parseInt(p[0],10)||0)*60+(parseInt(p[1],10)||0);}
function minToHm(m){var h=Math.floor(m/60),mm=m%60;return (h<10?'0':'')+h+':'+(mm<10?'0':'')+mm;}
function formatPrice(v){if(v==null||v==='')return '';var n=Number(v);if(isNaN(n))return String(v);return (n%1===0?n.toString():n.toFixed(2))+' $';}
function formatDate(d,lang){if(!d)return '';try{return new Date(d).toLocaleDateString(lang==='en'?'en-CA':'fr-CA',{year:'numeric',month:'long',day:'numeric'});}catch(e){return String(d);}}
async function getSettings(){var o={};try{var rows=await db.all('SELECT key,value FROM admin_settings');rows.forEach(function(r){o[r.key]=r.value;});}catch(e){}return o;}
function applyTextOverrides(t,settings,lang){for(var k in settings){if(k.indexOf('text_')===0&&k.slice(-(lang.length+1))==='_'+lang){var tk=k.slice(5,-(lang.length+1));if(tk)t[tk]=settings[k];}}return t;}
function buildT(settings,lang){return applyTextOverrides(Object.assign({},T[lang]||T.fr),settings,lang);}
function baseLocals(req,settings,lang,t){var pagePath=req.path==='/'?'.':req.path.replace(/^\//,'');return {t:t,lang:lang,settings:settings,user:req.user||null,pagePath:pagePath,cfg:{email:(services.config.contactEmail||''),phone:(services.config.contactPhone||''),address:(services.config.businessAddress||''),name:(services.config.businessName||services.config.displayName||'Parenthèse Détente')},formatPrice:formatPrice,formatDate:function(d){return formatDate(d,lang);},nl2br:nl2br};}
async function renderPage(req,res,view,extra){try{var settings=await getSettings();var lang=req.lang;var t=buildT(settings,lang);var base=baseLocals(req,settings,lang,t);res.render(view,Object.assign(base,extra||{}));}catch(e){res.status(500).send('Erreur');}}
function requireAdmin(req,res,next){if(!services.admin.isAdmin(req))return res.status(403).json({error:'Accès refusé'});next();}
function requireAdminPage(req,res,next){if(!services.admin.isAdmin(req))return res.redirect('admin/login');next();}
function norm(v){if(v==='')return null;return v;}
function bookingEmailHtml(b){return '<h2>Réservation</h2><p><strong>'+esc(b.service_name)+'</strong></p><p>'+esc(String(b.booking_date))+' — '+esc(b.booking_time)+' ('+esc(String(b.duration_min))+' min)</p><p>'+esc(b.customer_name)+' · '+esc(b.customer_phone)+' · '+esc(b.customer_email)+'</p><p>'+esc(b.customer_address)+' '+esc(b.city||'')+'</p><p>'+nl2br(b.notes||'')+'</p>';}

// ---- Admin SMS calendar notifications ----
// The admin can enter their own phone number (a tenant preference, stored in
// admin_settings — NOT a credential) to receive an SMS for each new booking.
// The SMS carries a Google Calendar "add event" link (a public render URL, no
// API key) so the admin can one-click add the appointment to their calendar.
function pad2(n){return (n<10?'0':'')+n;}
// Build a public Google Calendar template URL from a booking. Times are emitted
// as floating datetimes plus ctz=America/Toronto so they land at the correct
// local (Laurentides) wall-clock time on the admin's calendar.
function gcalLink(b){
 var date=String(b.booking_date||'').slice(0,10);
 var time=String(b.booking_time||'09:00').slice(0,5);
 var dp=date.split('-'),tp=time.split(':');
 var y=parseInt(dp[0],10),mo=parseInt(dp[1],10),d=parseInt(dp[2],10);
 if(!y||!mo||!d)return 'https://calendar.google.com/calendar';
 var startMin=(parseInt(tp[0],10)||0)*60+(parseInt(tp[1],10)||0);
 var endMin=startMin+(parseInt(b.duration_min,10)||60);
 function fmt(mins){var dayOff=Math.floor(mins/1440);var mm=((mins%1440)+1440)%1440;var base=new Date(Date.UTC(y,mo-1,d+dayOff));var yy=base.getUTCFullYear(),m2=base.getUTCMonth()+1,d2=base.getUTCDate();var h=Math.floor(mm/60),mi=mm%60;return ''+yy+pad2(m2)+pad2(d2)+'T'+pad2(h)+pad2(mi)+'00';}
 var dates=fmt(startMin)+'/'+fmt(endMin);
 var title=(b.service_name||'Rendez-vous')+(b.customer_name?(' — '+b.customer_name):'');
 var detailParts=[];
 if(b.customer_name)detailParts.push('Client : '+b.customer_name);
 if(b.customer_phone)detailParts.push('Tél. : '+b.customer_phone);
 if(b.customer_email)detailParts.push('Courriel : '+b.customer_email);
 if(b.notes)detailParts.push('Note : '+b.notes);
 var loc=(b.customer_address||'')+(b.city?(', '+b.city):'');
 var url='https://calendar.google.com/calendar/render?action=TEMPLATE'
  +'&text='+encodeURIComponent(title)
  +'&dates='+dates
  +'&details='+encodeURIComponent(detailParts.join('\n'))
  +'&location='+encodeURIComponent(loc)
  +'&ctz=America/Toronto';
 return url;
}
// Send the calendar SMS to the admin's configured number. Never throws — a
// failed SMS must not break the booking flow. `opts.force` bypasses the
// admin_sms_enabled toggle (used by the manual "send to my phone" action).
async function notifyAdminSms(b,opts){
 opts=opts||{};
 try{
  var settings=await getSettings();
  var phone=(settings.admin_sms_phone||'').trim();
  if(!phone)return {sent:false,reason:'no_phone'};
  var on=settings.admin_sms_enabled;
  var enabled=(on==='1'||on==='true'||on===true);
  if(!opts.force&&!enabled)return {sent:false,reason:'disabled'};
  if(!(services.sms&&typeof services.sms.send==='function'))return {sent:false,reason:'no_service'};
  var when=formatDate(b.booking_date,'fr')+' à '+String(b.booking_time||'').slice(0,5);
  var body='Parenthèse Détente — '+(opts.force?'rendez-vous':'nouveau rendez-vous')+'\n'
   +(b.service_name||'')+'\n'+when+'\n'
   +(b.customer_name||'')+(b.customer_phone?(' · '+b.customer_phone):'')+'\n'
   +'Ajouter à Google Agenda : '+gcalLink(b);
  await services.sms.send(phone,body);
  return {sent:true};
 }catch(e){return {sent:false,reason:'error'};}
}
async function paypalToken(){var id=ev('PAYPAL_CLIENT_ID'),secret=ev('PAYPAL_CLIENT_SECRET');if(!id||!secret)return null;var base=(ev('PAYPAL_MODE')==='sandbox')?'https://api-m.sandbox.paypal.com':'https://api-m.paypal.com';var auth=Buffer.from(id+':'+secret).toString('base64');var r=await services.fetch(base+'/v1/oauth2/token',{method:'POST',headers:{'Authorization':'Basic '+auth,'Content-Type':'application/x-www-form-urlencoded'},body:'grant_type=client_credentials'});var data=await r.json();if(!r.ok)return null;return {token:data.access_token,base:base};}

// Compute bookable time slots for a given date + service using the granular
// availability system: weekly windows (availability_rules, optionally scoped to
// a service and/or a validity period) minus blackout dates, minus overlapping
// bookings, minus the minimum lead time. Falls back to the legacy global
// settings only if no availability_rules exist yet.
async function computeAvailability(date,serviceId){
 var settings=await getSettings();
 var step=parseInt(settings.slot_minutes||'60',10)||60;
 var minHours=parseInt(settings.min_hours_ahead||'24',10);if(isNaN(minHours))minHours=0;
 var d=new Date(date+'T00:00:00');var dow=d.getDay();
 var sid=serviceId?parseInt(serviceId,10):null;if(isNaN(sid))sid=null;
 var duration=60;
 if(sid){var s=await db.get('SELECT duration_min FROM services WHERE id=$1',[sid]);if(s&&s.duration_min)duration=s.duration_min;}
 var bo=await db.get("SELECT 1 AS x FROM blackout_dates WHERE active=true AND start_date <= $1 AND COALESCE(end_date,start_date) >= $1 AND (service_id IS NULL OR service_id=$2) LIMIT 1",[date,sid]);
 if(bo)return {slots:[],closed:true};
 var rules;
 var any=await db.get('SELECT COUNT(*)::int AS n FROM availability_rules WHERE active=true');
 if(any&&any.n>0){
  rules=await db.all("SELECT start_time,end_time FROM availability_rules WHERE active=true AND day_of_week=$1 AND (service_id IS NULL OR service_id=$2) AND (valid_from IS NULL OR valid_from<=$3) AND (valid_to IS NULL OR valid_to>=$3) ORDER BY start_time ASC",[dow,sid,date]);
 }else{
  var days=(settings.booking_days||'1,2,3,4,5,6').split(',').map(function(x){return parseInt(x.trim(),10);});
  if(days.indexOf(dow)===-1)rules=[];else rules=[{start_time:settings.booking_start||'09:00',end_time:settings.booking_end||'19:00'}];
 }
 if(!rules.length)return {slots:[],closed:true};
 var existing=await db.all("SELECT booking_time,duration_min FROM bookings WHERE booking_date=$1 AND status <> 'cancelled'",[date]);
 var taken=existing.map(function(b){var bs=hmToMin(b.booking_time);return {s:bs,e:bs+(b.duration_min||60)};});
 var now=Date.now();var seen={};var slots=[];
 rules.forEach(function(w){var ws=hmToMin(w.start_time),we=hmToMin(w.end_time);for(var ts=ws;ts+duration<=we;ts+=step){var hm=minToHm(ts);if(seen[hm])continue;seen[hm]=true;var se=ts+duration,ok=true;for(var i=0;i<taken.length;i++){if(ts<taken[i].e&&se>taken[i].s){ok=false;break;}}var sdt=new Date(date+'T'+hm+':00');if(sdt.getTime()<now+minHours*3600000)ok=false;slots.push({time:hm,available:ok,_m:ts});}});
 slots.sort(function(a,b){return a._m-b._m;});slots.forEach(function(s){delete s._m;});
 return {slots:slots};
}

router.use(async function(req,res,next){var lang=(req.query&&req.query.lang)||(req.cookies&&req.cookies.pwa_lang)||'fr';if(lang!=='fr'&&lang!=='en')lang='fr';if(req.query&&req.query.lang){try{res.cookie('pwa_lang',lang,{maxAge:31536000000});}catch(e){}}req.lang=lang;if(req.method==='GET'&&req.path.indexOf('/api')!==0&&req.path.indexOf('/admin')!==0&&req.path.indexOf('.')===-1){try{await db.run('INSERT INTO site_visits (path) VALUES ($1)',[req.path]);}catch(e){}}next();});

