router.put('/api/admin/settings',requireAdmin,async function(req,res){try{var b=req.body||{};if(!b.key)return res.status(400).json({error:'key'});await db.run('INSERT INTO admin_settings (key,value,updated_at) VALUES ($1,$2,NOW()) ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=NOW()',[b.key,b.value==null?'':String(b.value)]);res.json({success:true});}catch(e){res.status(500).json({error:'err'});}});
router.post('/api/admin/upload',requireAdmin,async function(req,res){try{var b=req.body||{};if(!b.dataUri)return res.status(400).json({error:'no image'});if(!(services.cloudinary&&services.cloudinary.uploader&&typeof services.cloudinary.uploader.upload==='function'))return res.status(503).json({error:'Téléversement indisponible'});var result=await services.cloudinary.uploader.upload(b.dataUri,{folder:'parenthese-detente'});res.json({url:result.secure_url});}catch(e){res.status(500).json({error:'Téléversement échoué'});}});
router.post('/api/admin/generate-image',requireAdmin,async function(req,res){try{var b=req.body||{};if(!b.prompt)return res.status(400).json({error:'prompt'});var url=await services.ai.generateImage(b.prompt,{aspectRatio:b.aspectRatio||'4:3'});res.json({imageUrl:url});}catch(e){res.status(500).json({error:'Génération échouée. Téléversez manuellement.'});}});

// SMS calendar notifications — admin sends a test message to verify the number works.
router.post('/api/admin/sms/test',requireAdmin,async function(req,res){try{var b=req.body||{};var settings=await getSettings();var phone=((b.phone!=null?String(b.phone):'')||settings.admin_sms_phone||'').trim();if(!phone)return res.status(400).json({error:'Entrez d’abord votre numéro de téléphone.'});if(!(services.sms&&typeof services.sms.send==='function'))return res.status(503).json({error:'Le service SMS est indisponible.'});var sample={service_name:'Massage suédois',customer_name:'Client exemple',customer_phone:'(450) 555-0100',customer_email:'exemple@courriel.com',customer_address:'1 rue des Érables',city:'Saint-Sauveur',booking_date:new Date(Date.now()+86400000).toISOString().slice(0,10),booking_time:'14:00',duration_min:60,notes:'Ceci est un exemple.'};var body='Parenthèse Détente — SMS de test\nSi vous lisez ce message, les notifications fonctionnent.\nExemple d’ajout à Google Agenda : '+gcalLink(sample);await services.sms.send(phone,body);res.json({success:true});}catch(e){res.status(500).json({error:'L’envoi a échoué. Vérifiez le numéro et réessayez.'});}});
// Re-send the calendar SMS for an existing booking (one-click "send to my phone").
router.post('/api/admin/bookings/:id/notify',requireAdmin,async function(req,res){try{var bk=await db.get('SELECT * FROM bookings WHERE id=$1',[req.params.id]);if(!bk)return res.status(404).json({error:'Réservation introuvable.'});var settings=await getSettings();if(!(settings.admin_sms_phone||'').trim())return res.status(400).json({error:'Ajoutez votre numéro dans Réglages › Notifications SMS.'});if(!(services.sms&&typeof services.sms.send==='function'))return res.status(503).json({error:'Le service SMS est indisponible.'});var r=await notifyAdminSms(bk,{force:true});if(!r.sent)return res.status(502).json({error:'L’envoi a échoué. Réessayez.'});res.json({success:true});}catch(e){res.status(500).json({error:'L’envoi a échoué.'});}});

