router.get('/admin',async function(req,res){if(!services.admin.isAdmin(req))return res.redirect('admin/login');try{var settings=await getSettings();var lang='fr';var bk=await db.get('SELECT COUNT(*)::int AS n FROM bookings');var pend=await db.get("SELECT COUNT(*)::int AS n FROM bookings WHERE status='pending'");var sv=await db.get('SELECT COUNT(*)::int AS n FROM services WHERE active=true');var po=await db.get('SELECT COUNT(*)::int AS n FROM posts');var vt=await db.get('SELECT COUNT(*)::int AS n FROM site_visits');var v7=await db.get("SELECT COUNT(*)::int AS n FROM site_visits WHERE created_at > NOW() - INTERVAL '7 days'");var rev=await db.get("SELECT COALESCE(SUM(price),0) AS s FROM bookings WHERE payment_status='paid'");var subs=await db.get('SELECT COUNT(*)::int AS n FROM form_submissions');var win=await db.get('SELECT COUNT(*)::int AS n FROM availability_rules WHERE active=true');var blk=await db.get("SELECT COUNT(*)::int AS n FROM blackout_dates WHERE active=true AND COALESCE(end_date,start_date) >= CURRENT_DATE");var recent=await db.all("SELECT * FROM bookings WHERE status <> 'cancelled' ORDER BY booking_date DESC, booking_time DESC LIMIT 6");var smsPhone=(settings.admin_sms_phone||'').trim();var smsEnabled=(settings.admin_sms_enabled==='1'||settings.admin_sms_enabled==='true');res.render('admin',{stats:{bookings:bk.n,pending:pend.n,services:sv.n,posts:po.n,visitsTotal:vt.n,visits7:v7.n,revenue:Number(rev.s),submissions:subs.n,windows:win.n,blackouts:blk.n},recent:recent,smsPhone:smsPhone,smsEnabled:smsEnabled,formatPrice:formatPrice,formatDate:function(d){return formatDate(d,'fr');}});}catch(e){res.status(500).send('Erreur');}});
